/* Repository-owned JSON Lines adapter for the pinned Girving Kalah source. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "canonical_kvtb.h"
#include "crunch.cilkh"

static long long cumulative_nodes, cumulative_tt_probes, cumulative_tt_hits;
static const char *at(const char *s, const char *key) { const char *p = strstr(s, key); return p ? strchr(p, ':') : 0; }
static int integer(const char *s, const char *key, int *v) { char *e; const char *p = at(s,key); if (!p) return 0; *v = strtol(p+1,&e,10); return e != p+1; }
static int array(const char *s, const char *key, int *v, int n) { const char *p=at(s,key); int i; char *e; if (!p || !(p=strchr(p,'['))) return 0; for(i=0,p++;i<n;i++,p=e+1) { v[i]=strtol(p,&e,10); if(e==p || (i+1<n && *e!=',')) return 0; } return 1; }
static void readp(const char *s, position *p) { int a[12],b[2],i,j; if(!array(s,"\"pits\"",a,12)||!array(s,"\"stores\"",b,2)||!integer(s,"\"player\"",&i)||i<0||i>1) exit(2); for(j=0;j<6;j++){p->a[j]=a[j];p->a[j+7]=a[j+6];} p->a[6]=b[0]; p->a[13]=b[1]; p->s=i;p->w=-1; }
static int active(const position *p) { int i,n=0; for(i=0;i<6;i++)n+=p->a[i]+p->a[i+7]; return n; }
static int value(position p) { char m[MAXMVC]; int d,r; if(p.w>=0)return p.a[6]-p.a[13]; r=solve(m,p,200,&d,0,SF_GUESS|SF_STALE); return p.s ? -r:r; }
static void board(position p, int x) { int i,margin=p.a[6]-p.a[13]; for(i=0;i<6;i++)margin+=p.a[i]-p.a[i+7]; printf("\"pits\":["); for(i=0;i<6;i++)printf("%s%d",i?",":"",p.a[i]);for(i=0;i<6;i++)printf(",%d",p.a[i+7]);printf("],\"stores\":[%d,%d],\"player\":%d,\"extra_turn\":%s,\"terminal\":%s,\"final_margin\":%d",p.a[6],p.a[13],p.s,x && p.w < 0 ? "true":"false",p.w>=0?"true":"false",margin); }
static void metrics(clock_t cpu, struct timespec wall, int root_active) { struct timespec now; int i,first=1; double cpu_seconds=(double)(clock()-cpu)/CLOCKS_PER_SEC,wall_seconds; clock_gettime(CLOCK_MONOTONIC,&now); wall_seconds=(double)(now.tv_sec-wall.tv_sec)+(double)(now.tv_nsec-wall.tv_nsec)/1000000000.0; cumulative_nodes+=stat.nodes; cumulative_tt_probes+=stat.peeks; cumulative_tt_hits+=stat.ha_lookups; printf(",\"metrics\":{\"status\":\"completed\",\"wall_time_seconds\":%.9f,\"cpu_time_seconds\":%.9f,\"forward_search_nodes\":%lld,\"maximum_search_depth\":%d,\"tt_probes\":%lld,\"tt_hits\":%lld,\"tablebase_lookups\":%lld,\"tablebase_hits\":%lld,\"tablebase_hits_by_tier\":{",wall_seconds,cpu_seconds,stat.nodes,stat.maxdepth,stat.peeks,stat.ha_lookups,canonical_tablebase_request_lookups(),canonical_tablebase_request_hits()); for(i=0;i<=20;i++)if(canonical_tablebase_tier_hits(i)) { printf("%s\"%d\":%lld",first?"":",",i,canonical_tablebase_tier_hits(i)); first=0; } printf("},\"first_tablebase_hit_depth\":%d,\"minimum_tablebase_hit_tier\":%d,\"maximum_tablebase_hit_tier\":%d,\"root_active_stones\":%d,\"cumulative_cache\":{\"tt_probes\":%lld,\"tt_hits\":%lld,\"tablebase_hits\":%lld}}",canonical_tablebase_first_hit_depth(),canonical_tablebase_min_hit_tier(),canonical_tablebase_max_hit_tier(),root_active,cumulative_tt_probes,cumulative_tt_hits,canonical_tablebase_hits()); }
static void begin_request(void) { init_stat(); canonical_tablebase_reset_request_metrics(); }
static void apply(const char *s) { position p;int a,x,extra;readp(s,&p);if(!integer(s,"\"action\"",&a)||a<0||a>=6||!bin(p,a))exit(2);extra=(a+bin(p,a))%13==6;x=move(&p,a);if(p.w>=0&&!extra)p.s=1-p.s;printf("{\"operation\":\"apply\",");board(p,extra);puts("}"); }
static void solveone(const char *s) { position p;clock_t cpu;struct timespec wall;readp(s,&p);begin_request();cpu=clock();clock_gettime(CLOCK_MONOTONIC,&wall);printf("{\"operation\":\"solve\",");board(p,0);printf(",\"exact_value\":%d",value(p));metrics(cpu,wall,active(&p));puts("}"); }
static void diagnose(const char *s) { position p;canonical_tablebase_info info;readp(s,&p);if(!canonical_tablebase_diagnostics(&p,&info)){puts("{\"error\":\"tablebase lookup unavailable\"}");return;}printf("{\"operation\":\"diagnose\",\"active_stones\":%d,\"rank\":%llu,\"offset\":%llu,\"raw_value\":%d,\"store_margin\":%d,\"upstream_value\":%d,\"player_zero_value\":%d}\n",info.active_stones,(unsigned long long)info.rank,(unsigned long long)info.offset,info.raw_value,info.store_margin,info.upstream_value,info.player_zero_value); }
static void label(const char *s) { position p,c;int a,x,v,best,first=1,values[6];clock_t cpu;struct timespec wall;readp(s,&p);begin_request();cpu=clock();clock_gettime(CLOCK_MONOTONIC,&wall);best=p.s?10000:-10000;printf("{\"operation\":\"label\",");board(p,0);printf(",\"action_values\":{");for(a=0;a<6;a++)if(bin(p,a)){c=p;x=move(&c,a);v=c.w>=0?c.a[6]-c.a[13]:value(c);values[a]=v;if((!p.s&&v>best)||(p.s&&v<best))best=v;printf("%s\"%d\":%d",first?"":",",a,v);first=0;}printf("},\"exact_value\":%d,\"optimal_actions\":[",best);first=1;for(a=0;a<6;a++)if(bin(p,a)&&values[a]==best){printf("%s%d",first?"":",",a);first=0;}printf("],\"action_margins\":{");first=1;for(a=0;a<6;a++)if(bin(p,a)){printf("%s\"%d\":%d",first?"":",",a,p.s ? values[a]-best : best-values[a]);first=0;}printf("}");metrics(cpu,wall,active(&p));puts("}"); }
int main(void) { char s[4096],*tablebase=getenv("NATIVE_CANONICAL_KVTB");init_hash(16,0);if(tablebase&&!canonical_tablebase_load(tablebase))return 3;while(fgets(s,sizeof(s),stdin)){if(strstr(s,"apply"))apply(s);else if(strstr(s,"diagnose"))diagnose(s);else if(strstr(s,"solve"))solveone(s);else if(strstr(s,"label"))label(s);else return 2;fflush(stdout);}canonical_tablebase_close();close_hash();return 0; }
